import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第三卷 潮汐 · 第67章 二十五颗","description":"","frontmatter":{},"headers":[],"relativePath":"第67章_二十五颗.md","filePath":"第67章_二十五颗.md"}'),r={name:"第67章_二十五颗.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第三卷-潮汐-·-第67章-二十五颗" tabindex="-1">第三卷 潮汐 · 第67章 二十五颗 <a class="header-anchor" href="#第三卷-潮汐-·-第67章-二十五颗" aria-label="Permalink to &quot;第三卷 潮汐 · 第67章 二十五颗&quot;">​</a></h1><p>我是沈聿。</p><p>高二秋冬交界，南雾县的雾散不干净。早晨走去学校，鞋面沾着薄薄水汽，呼吸里全是潮湿的味道。到了教室，桌椅摸上去凉凉的。江苒坐在靠窗的位置，用指尖划开窗上的白雾，外面的操场露出一角。</p><p>她桌肚里放着一只玻璃罐，里面装着纸星星。</p><p>课间，林小满凑过来，趴在桌边往里看，声音压得很低。</p><p>“又多了呀，我来数数。”</p><p>江苒把罐子推过去，玻璃底在桌面滑出轻响。</p><p>“轻点晃，昨晚折的角还没压平。”</p><p>阳光从雾缝透进来，落在玻璃上，粉的黄的蓝的星星堆在一起，像退潮后留在沙滩上的贝壳。林小满一颗一颗拨着数，嘴唇轻轻动着。</p><p>陈默抱着篮球走过来，额头带汗。</p><p>“数什么呢，这么投入。”</p><p>“星星，江苒折的。”林小满头也没抬。</p><p>顾远探头看了一眼，笑着说。</p><p>“颜色好看，叠得也紧。”</p><p>江苒有些不好意思，把头发别到耳后。</p><p>“纸都是旧练习纸的背面，颜色是我自己涂的。”</p><p>我在她旁边坐下，能闻到纸上淡淡的彩笔味，还混着窗外飘来的桂花香，已经很淡了。指尖碰到玻璃罐，凉凉的，带着冬天的预感。</p><p>“现在多少颗了？”我问。</p><p>江苒眼里有笑。</p><p>“你猜。”</p><p>林小满举手，大声宣布。</p><p>“我数出来了，二十五颗。”</p><p>陈默把球放在地上，发出一声闷响。</p><p>“二十五，挺快了呀，上次才十几颗。”</p><p>江苒把罐子抱回来，轻轻摇了一下。纸星星碰撞，发出很轻的沙沙声，像风吹过芦苇。我想起宋阿婆家门口的贝壳风铃，风一吹就响，也是这样细碎的动静。</p><p>“快了。”江苒小声说。“我想折满一罐，放在窗台上，冬天看着暖和。”</p><p>叶老师从门口走过，看了我们一眼，只是笑了笑。她抱着作业本，脚步很轻。教室里人声渐多，暖气还没来，大家穿得很厚，袖口摩擦桌面，窸窣作响。</p><p>何晓从前排转过头，递给江苒一颗海盐糖。</p><p>“给你，折星星费眼睛。”</p><p>江苒剥开糖纸放进嘴里，腮帮鼓起一点。</p><p>“谢谢，好甜。”</p><p>何晓又递给我一颗。</p><p>“沈聿也有，别说我偏心。”</p><p>糖纸在手心窸窣作响。糖放进嘴里，先咸后甜，舌尖慢慢润起来。窗外雾淡了一点，远处传来海鸥的叫声，断断续续，带着咸腥。</p><p>林小满盯着罐子，忽然问。</p><p>“有没有哪颗是特别的，藏着秘密的那种？”</p><p>江苒挑出一颗淡蓝色的，托在掌心。</p><p>“这颗折得最久，那晚灯光暗，对着小台灯折的，角对了好几次。”</p><p>陈默凑近看。</p><p>“还挺周正。”</p><p>顾远用胳膊碰他。</p><p>“人家这是心意。”</p><p>我看着那颗星星，棱角分明，颜色均匀。江苒指腹带着薄茧，那是折纸留下的。她把星星放回去，拧紧罐盖，动作很轻。</p><p>晚自习时，教室只剩笔尖划纸的声音。江苒拿出裁好的纸条，继续折。林小满搬凳子坐在旁边学，手指笨拙，怎么也卷不紧。</p><p>“我手太笨了，折出来是扁的。”</p><p>江苒握住她的手，一步一步教。</p><p>“先绕个圈，留个小尾巴，慢慢收紧，别太用力。”</p><p>陈默掏出一盘旧磁带晃了晃，壳子已经磨白。</p><p>“我负责放歌，折星星总得有点动静。”</p><p>磁带放进旧录音机，沙沙的底噪先出来，随后是缓慢的老歌，带着海风的味道。秦浩送来一叠彩纸，赵晴拿来一只小玻璃瓶，系着绳子。</p><p>“林小满，你折的就装这里，和大罐做伴。”赵晴说。</p><p>林小满抱着小瓶欢呼，差点碰翻桌子。叶老师站在门口看着，眼里全是笑，走过来摸了摸玻璃罐。</p><p>“二十五颗了，真快。满罐了老师给你们拍照。”</p><p>江苒点头，脸颊红扑扑的。</p><p>“到时候一起拍。”</p><p>放学时雾又起来，校门口宋阿婆守着小店，炉子里飘出烤红薯的香气，热乎乎的。她往江苒手里塞了两颗海盐糖，又给我和林小满各塞了一颗。</p><p>“星星罐真好看，折满了拿来给阿婆看看。”宋阿婆笑着说。</p><p>江苒点头，眼睛亮亮的。</p><p>“一定，阿婆等我。”</p><p>回家的巷子很窄，墙上长着青苔，脚步声在雾里清晰可闻。江苒的书包轻轻晃，玻璃罐碰着书本，发出闷闷的响。巷口有人放旧磁带，歌声断断续续，带着沙沙的底噪。她忽然问我，折满一罐许愿会实现吗，我说你这么认真，一定会。她笑起来，睫毛上沾着雾气，亮晶晶的。</p><p>那晚雾很浓，远处隐约有潮汐声。糖的甜味化开，纸条的触感留在指腹，歌声混着笑声。我看着灯光下江苒的发顶，心里觉得，二十五这个数字，像涨潮前的水位，马上就要漫上来。</p><p>夜里起风，窗户被吹得轻响，风里带着海的味道。我摸到口袋里的糖纸，展开又攥紧，上面还留着甜味，想起她说快了时的眼神，像退潮前海面最后的亮。</p><p>第二天早晨，教室比平时安静。江苒来得很早，罐子放在桌上，盖子开着。我顺手数了数，怎么数都只有二十四颗，心跳忽然快起来。</p><p>“江苒，好像少了一颗，昨晚还好好的？”</p><p>她脸色有点白，手指攥着衣角。</p><p>“没有掉，是我拿出来了。”</p><p>“拿去哪了？”</p><p>她从口袋掏出那颗淡蓝色星星，放在桌上，声音很轻。</p><p>“昨晚我把这颗拆开了，里面写了字。本来想等满罐再给你看，可我等不及了。”</p><p>我拿起那颗拆开一半的星星，纸条展开一角，字迹很小，被折痕压住，看不清。窗外雾气正浓，上课铃响起，叶老师走进教室，手里拿着一盘旧磁带，目光落在我们这桌。</p><p>江苒看着我，嘴唇动了动，像有话要说，又咽了回去。罐子里二十四颗星星安静躺着，空出的位置刚好能放下一颗，而她手心的那颗，正微微发烫。</p>',71)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
